def append(q,proof,origin=None):
 q=copy.deepcopy(q);q['id']=f'gb2-{len(BANK)+1:03}'
 q.update(section='quantitative',reviewStatus='pending_human_review',sourceType='original_draft',bankVersion='gables-v2',provenance={'origin':'original AI-assisted authorship','priorId':origin,'referenceUse':'format calibration only'})
 # Rotate independently of source choices; use each key position 25 times.
 choices=q['choices'];answer=choices['ABCD'.index(q['guide']['correctChoiceId'])];target=POSITIONS[len(BANK)];shift=(choices.index(answer)-target)%4
 q['choices']=choices[shift:]+choices[:shift];q['guide']['correctChoiceId']='ABCD'[target]
 proof=copy.deepcopy(proof)
 if proof['kind']=='relations':proof['predicates']=proof['predicates'][shift:]+proof['predicates'][:shift]
 q['answerFormat']=q.get('answerFormat','numeric');BANK.append(q);PROOFS[q['id']]=proof
 CHANGES.append({'id':q['id'],'priorId':origin,'action':'retained/rechecked' if origin else 'new original item'})
 return q

