 q={'skill':skill,'format':fmt,'templateFamily':family,'difficulty':d,'stem':stem,'choices':choices,'guide':{'correctChoiceId':'ABCD'[choices.index(answer)],'explanation':explanation,'shortcut':tip},'answerFormat':answerFormat}
 if visual:q['visual']=visual
 return append(q,proof,origin)
