def visual(family,d,stem,opts,answer,explanation,tip,diagram,proof):
 return new('numeric_comparison','geometric_comparison',family,d,stem,opts,answer,explanation,tip,proof,visual=diagram,answerFormat='relationship' if proof['kind']=='relations' else 'numeric')
